def sort_by_score_dedup(items):
    best = {}

    for item in items:
        if "id" not in item:
            continue
        score = item.get("score")
        if not isinstance(score, (int, float)):
            continue

        item_id = item["id"]
        if item_id not in best or score > best[item_id]["score"]:
            best[item_id] = item

    return sorted(best.values(), key=lambda x: x["score"])


