def make_hashable(obj):
    if isinstance(obj, dict):
        return ("dict", tuple(sorted((k, make_hashable(v)) for k, v in obj.items())))
    if isinstance(obj, list):
        return ("list", tuple(make_hashable(x) for x in obj))
    if isinstance(obj, tuple):
        return ("tuple", tuple(make_hashable(x) for x in obj))
    if isinstance(obj, set):
        return ("set", tuple(sorted(make_hashable(x) for x in obj)))
    return obj

def remove_duplicates(items):
    seen = set()
    result = []
    for item in items:
        key = make_hashable(item)
        if key not in seen:
            seen.add(key)
            result.append(item)
    return result


